<script>
import { mapGetters } from "vuex";
import axios from "axios";
import MoneyFormat from "@/utils/moneyFormat";
import logs from "@/utils/logs";
import companyLogo from "@/utils/companyLogo";
// PDF Generator
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
pdfMake.vfs = pdfFonts.pdfMake.vfs;
import moment from "moment";
import DateFormat from "@/utils/dateFormat";


export default {
  name: "item-loan",

  data: () => ({
    allAmortizations: [],
    customerLoanAmortization: [],
    paidAmortizations: [],
    loanDebts: [],
    currentDebt: [],
    totalDebtAmount: 0,
    baseDebtAmount: 0,
    paymentReference: "",
    debitBalance: 0,
    amountReceived: 0,
    paymentDate: moment().format("YYYY-MM-DD"),
    phoneNumber: "",
    amortizationLoanId: 0,
    currentAmortization: {},
    installmentOrder: 0,
    diffDays: 0,
    forfeitValue: 0,
    total2Pay: 0,

    paymentMethod: 1,

    totalAmortizationForfeit: 0,
    receiptUrl: "",
    documentName: "",
    selectedFile: "",
    uploadValue: 0,

    options: [
      { value: 1, text: "Boca do Caixa" },
      { value: 2, text: "Depósito Bancário" },
      { value: 3, text: "Transferência Bancária" },
      { value: 4, text: "POS" },
      { value: 5, text: "Cheque" },
      { value: 6, text: "M-Pesa USSD" },
      { value: 7, text: "M-Pesa Open API" },
      { value: 8, text: "E-Mola" },
    ],
    today: moment(),
  }),

  props: ["currentLoan"],

  created() {
    this.getAmortizationLoans();
    this.getLoanDebts();
  },

  watch: {
    paymentMethod: function () {
      if (this.paymentMethod != 1) {
        this.paymentReference = "";
      }
    },
    amountReceived: function () {
      this.debitBalance = this.total2Pay - this.amountReceived;
    },
    paymentDate: function () {
      if (!this.currentAmortization || !this.currentAmortization.dueDate) return;

      this.diffDays = moment(this.paymentDate).diff(
        this.currentAmortization.dueDate,
        "days"
      );

      // Juros de mora = prestação × (forfeit / 100) × dias em atraso
      // company.forfeit é a taxa diária em percentagem (ex: 2 = 2%/dia)
      const dailyRate = this.company.forfeit / 100;
      const baseAmount = this.currentAmortization.installment;
      this.forfeitValue = this.diffDays > 0 ? Math.round(baseAmount * dailyRate * this.diffDays * 100) / 100 : 0;
      this.total2Pay = this.forfeitValue + baseAmount;
      this.amountReceived = this.total2Pay;
    },
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "token",
      "currentCustomer",
      "customerTranzactions",
      "company",
    ]),

    /**
     * Total de juros calculado pela fórmula do sistema francês (Price)
     * Total Juros = (PMT × n) - Capital
     */
    computedTotalInterest() {
      const principal = parseFloat(this.currentLoan.amount) || 0;
      const rate = parseFloat(this.currentLoan.interestRate) || 0;
      const n = parseInt(this.currentLoan.numberOfInstallments) || 1;

      if (principal <= 0) return 0;
      if (rate === 0) return 0;

      const factor = Math.pow(1 + rate, n);
      const pmt = principal * (rate * factor) / (factor - 1);
      const totalInterest = (pmt * n) - principal;

      return Math.round(totalInterest * 100) / 100;
    },

    /**
     * Total da dívida calculado pela fórmula do sistema francês (Price)
     * Total = PMT × n (soma de todas as prestações)
     */
    computedTotalDebt() {
      const principal = parseFloat(this.currentLoan.amount) || 0;
      const rate = parseFloat(this.currentLoan.interestRate) || 0;
      const n = parseInt(this.currentLoan.numberOfInstallments) || 1;

      if (principal <= 0) return 0;
      if (rate === 0) return principal;

      const factor = Math.pow(1 + rate, n);
      const pmt = principal * (rate * factor) / (factor - 1);
      const totalDebt = pmt * n;

      return Math.round(totalDebt * 100) / 100;
    },
  },

  methods: {
    buildDocumentLink(documentFileUrl) {
      if (!documentFileUrl) return "#";

      const normalizedUrl = String(documentFileUrl).trim();
      if (/^https?:\/\//i.test(normalizedUrl)) return normalizedUrl;

      const fileName = normalizedUrl.split("/").filter(Boolean).pop();
      if (!fileName) return "#";

      return `/api/document/file/${encodeURIComponent(fileName)}`;
    },

    getReceiptUrlForAmortization(amortization) {
      const transactionWithReceipt = this.customerTranzactions.find((transaction) => {
        return (
          Number(transaction.amortizationLoanId) === Number(amortization.id) &&
          Boolean(transaction.receiptUrl)
        );
      });
      return transactionWithReceipt ? transactionWithReceipt.receiptUrl : "";
    },

    getAmortizationLoans() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .get(
          `/api/loan/amortization/${this.currentLoan.id}/${this.company.forfeit}`
        )
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.allAmortizations = data.result;
            this.paidAmortizations = data.result.filter((ammort) => {
              return ammort.status === 1;
            });
            this.customerLoanAmortization = data.result.filter((ammort) => {
              return ammort.status <= 0;
            });
          } else {
            this.showToast("Erro!", "danger", data.message);
            this.allAmortizations = [];
            this.paidAmortizations = [];
            this.customerLoanAmortization = [];
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.allAmortizations = [];
          this.paidAmortizations = [];
          this.customerLoanAmortization = [];
        });
    },

    getLoanDebts() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .get(`/api/debt/${this.currentLoan.id}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.loanDebts = data.result;
          } else {
            this.showToast("Erro!", "danger", data.message);
            this.loanDebts = [];
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.loanDebts = [];
        });
    },

    getTotalDebt(amortization) {
      const debt = this.loanDebts.filter((a) => {
        return a.amortisationId === amortization.id;
      });
      this.currentDebt = debt.length > 0 ? debt[0] : [];
      const total = debt.length > 0 ? debt[0].debtAmount : 0;
      const diffDays = moment().diff(
        debt.length > 0 ? debt[0].updatedAt : moment(),
        "days"
      );

      // Juros de mora sobre dívida = valor em dívida × (forfeit / 100) × dias
      const dailyRate = this.company.forfeit / 100;
      const totalForfeit = diffDays > 0 ? Math.round(total * dailyRate * diffDays * 100) / 100 : 0;
      this.totalAmortizationForfeit = totalForfeit;
      this.baseDebtAmount = total;
      this.totalDebtAmount = totalForfeit + total;
      return total + totalForfeit;
    },

    // Calcular juros de mora da dívida (para exibição na tabela)
    getDebtForfeit(amortization) {
      const debt = this.loanDebts.filter((a) => {
        return a.amortisationId === amortization.id;
      });
      if (debt.length === 0) return 0;
      const total = debt[0].debtAmount;
      const diffDays = moment().diff(debt[0].updatedAt, "days");
      const dailyRate = this.company.forfeit / 100;
      return diffDays > 0 ? Math.round(total * dailyRate * diffDays * 100) / 100 : 0;
    },

    // Calcular total da dívida (para exibição na tabela)
    getDebtTotal(amortization) {
      const debt = this.loanDebts.filter((a) => {
        return a.amortisationId === amortization.id;
      });
      if (debt.length === 0) return 0;
      const total = debt[0].debtAmount;
      const forfeit = this.getDebtForfeit(amortization);
      return total + forfeit;
    },

    payDebt(amortization) {
      this.currentAmortization = amortization;
      this.getTotalDebt(amortization);

      this.total2Pay = this.totalDebtAmount;
      this.debitBalance = 0;
      this.paymentReference = `${this.currentCustomer.accountNumber}PY${this.currentDebt.amortisationId}`;
      this.paymentMethod = 1;
      this.phoneNumber = this.currentCustomer.customerPhone;
      this.amortizationLoanId = amortization.id;
      this.installmentOrder = amortization.installmentOrder;
      this.amountReceived = this.totalDebtAmount;
      this.paymentDate = moment().format("YYYY-MM-DD");

      this.$refs["place-debt-payment"].show();
    },

    convertMoney(value) {
      return MoneyFormat.formatMoney(value);
    },

    // Calcula juros de mora com base na data actual (para exibição na tabela)
    computeForfeitToday(amortization) {
      const diffDays = moment().diff(amortization.dueDate, "days");
      if (diffDays <= 0) return 0;
      const dailyRate = this.company.forfeit / 100;
      return Math.round(amortization.installment * dailyRate * diffDays * 100) / 100;
    },

    // Calcula juros de mora com base na data de pagamento seleccionada (para a modal)
    calculateForfeit(amortization) {
      const diffDays = moment(this.paymentDate).diff(
        amortization.dueDate,
        "days"
      );
      if (diffDays <= 0) return 0;
      const dailyRate = this.company.forfeit / 100;
      return Math.round(amortization.installment * dailyRate * diffDays * 100) / 100;
    },

