    getPaymentMethodName(method) {
      const methods = {
        1: 'Boca do Caixa',
        2: 'Depósito Bancário',
        3: 'Transferência Bancária',
        4: 'POS',
        5: 'Cheque',
        6: 'M-Pesa USSD',
        7: 'M-Pesa Open API',
        8: 'E-Mola',
      };
      return methods[method] || 'Outro';
    },

    addPayment(amortization) {
      this.currentAmortization = amortization;
      this.$refs["place-payment"].show();
      this.paymentReference = `${this.currentCustomer.accountNumber}PY${amortization.id}`;
      this.paymentMethod = 1;
      this.phoneNumber = this.currentCustomer.customerPhone;
      this.amortizationLoanId = amortization.id;
      this.installmentOrder = amortization.installmentOrder;

      // Usar valores calculados pelo backend
      this.diffDays = amortization.lateDays || 0;
      this.forfeitValue = amortization.latePaymentInterest || 0;
      this.total2Pay = amortization.installment + this.forfeitValue;
      this.amountReceived = this.total2Pay;
      this.debitBalance = 0;

      // Definir a data de pagamento como hoje
      this.paymentDate = moment().format("YYYY-MM-DD");
    },

    payViaMpesa() {
      if (this.phoneNumber.length != 12) {
        this.showToast("Aviso!", "warning", "O número que digitou é inválido.");
        return;
      } else {
        const passingValues = {
          from: this.phoneNumber + "",
          reference: this.currentCustomer.accountNumber + "",
          amount: this.amountReceived + "",
          transaction:
            this.currentCustomer.accountNumber + "PY" + this.amortizationLoanId,
          loanId: this.currentLoan.loanId,
          paymentDate: this.paymentDate,
        };

        this.$store.commit("LOADING_STATUS", true);
        axios
          .put(`/api/mpesa/receive`, passingValues)
          .then((res) => {
            const data = res.data;
            if (data.success == true) {
              const response = data.result;
              if (
                response.output_ResponseDesc == "Request processed successfully"
              ) {
                this.showToast(
                  "Sucesso!",
                  "success",
                  "Pagamento efectuado com sucesso."
                );
                this.addTransaction(response);
              }
            } else {
              this.showToast("Erro!", "danger", data.message);
              const response = data.result;
              if (response.output_ResponseDesc == "Duplicate Transaction") {
                this.showToast(
                  "Erro!",
                  "danger",
                  "Transacção duplicada, tente mais tarde"
                );
              }
            }
            this.$store.commit("LOADING_STATUS", false);
          })
          .catch((err) => {
            this.showToast("Erro!", "danger", err.message);
            this.$store.commit("LOADING_STATUS", false);
            console.log(err);
          });
      }
    },

    addTransaction(mpesa) {
      const passingValues = {
        tranzactionReference: mpesa.output_TransactionID.toUpperCase(),
        accountNumber: this.currentCustomer.accountNumber,
        phoneNumber: this.phoneNumber,
        staffName: this.user.name,
        companyId: this.company.id,
        amount: this.amountReceived,
        latePaymentInterest: this.calculateForfeit(this.currentAmortization),
        interestRateAmount: this.currentAmortization.rateAmount,
        paymentMethod: this.paymentMethod,
        loanId: this.currentAmortization.loanId,
        paymentDate: this.paymentDate,
        amortizationLoanId: this.amortizationLoanId,
        receiptUrl: this.receiptUrl,
        description: `Recebemos ${MoneyFormat.formatMoney(
          this.amountReceived
        )}, referente ao pagamento da ${
          this.installmentOrder
        } com a referência ${mpesa.output_TransactionID.toUpperCase()}.`,
      };

      this.$store.commit("LOADING_STATUS", true);
      axios
        .post(`/api/tranzaction`, passingValues)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast(
              "Sucesso!",
              "success",
              "Pagamento efectuado com sucesso"
            );
            const logsParams = logs(
              this.user,
              `${passingValues.description}`,
              "Desembolso de crédito"
            );
            this.$store.dispatch("addLog", logsParams);
            if (parseFloat(this.debitBalance) > 0) this.insertDebt();
          } else {
            this.showToast("Erro!", "danger", data.message);
          }
          this.getAmortizationLoans();
          this.getLoanDebts();
          this.getCustomerTranzactions();
          this.$refs["place-payment"].hide();
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.$refs["place-payment"].hide();
        });
    },

    finalizepayment() {
      const passingValues = {
        tranzactionReference: this.paymentReference,
        accountNumber: this.currentCustomer.accountNumber,
        phoneNumber: "Não disponível",
        staffName: this.user.name,
        companyId: this.company.id,
        amount: this.amountReceived,
        latePaymentInterest: this.forfeitValue,
        interestRateAmount: this.currentAmortization.rateAmount,
        paymentMethod: this.paymentMethod,
        paymentDate: this.paymentDate,
        loanId: this.currentLoan.id,
        amortizationLoanId: this.amortizationLoanId,
        receiptUrl: this.receiptUrl,
        description: `Recebemos ${MoneyFormat.formatMoney(
          this.amountReceived
        )}, referente ao pagamento da prestação nº ${
          this.installmentOrder
        } com a referência ${this.paymentReference.toUpperCase()}.`,
      };

      if (passingValues.tranzactionReference.length < 4) {
        this.showToast(
          "Aviso!",
          "warning",
          "Digite a referência do pagamento por favor."
        );
        return;
      } else {
        this.$store.commit("LOADING_STATUS", true);
        axios
          .post(`/api/tranzaction`, passingValues)
          .then((res) => {
            const data = res.data;
            if (data.success == true) {
              this.showToast(
                "Sucesso!",
                "success",
                "Pagamento efectuado com sucesso"
              );
              const logsParams = logs(
                this.user,
                `${passingValues.description}`,
                "Desembolso de crédito"
              );
              this.$store.dispatch("addLog", logsParams);
              if (parseFloat(this.debitBalance) > 0) this.insertDebt();
            } else {
              this.showToast("Erro!", "danger", data.message);
            }
            this.getAmortizationLoans();
            this.getLoanDebts();
            this.getCustomerTranzactions();
            this.$refs["place-payment"].hide();
            this.$store.commit("LOADING_STATUS", false);
          })
          .catch((err) => {
            this.showToast("Erro!", "danger", err.message);
            this.$store.commit("LOADING_STATUS", false);
            this.$refs["place-payment"].hide();
          });
      }
    },

    finalizeDebtpayment() {
      const passingValues = {
        tranzactionReference: this.paymentReference,
        accountNumber: this.currentCustomer.accountNumber,
        phoneNumber: "Não disponível",
        staffName: this.user.name,
        companyId: this.company.id,
        amount: this.amountReceived,
        latePaymentInterest: this.totalAmortizationForfeit,
        interestRateAmount: 0,
        paymentMethod: this.paymentMethod,
        paymentDate: this.paymentDate,
        loanId: this.currentLoan.id,
        amortizationLoanId: this.currentDebt.amortisationId,
        receiptUrl: this.receiptUrl,
        description: `Recebemos ${MoneyFormat.formatMoney(
          this.amountReceived
        )}, referente ao pagamento da dívida da prestação nº ${
          this.installmentOrder
        } com a referência ${this.paymentReference.toUpperCase()}.`,
      };

      if (passingValues.tranzactionReference.length < 4) {
        this.showToast(
          "Aviso!",
          "warning",
          "Digite a referência do pagamento por favor."
        );
        return;
      } else {
        this.$store.commit("LOADING_STATUS", true);
        axios
          .post(`/api/tranzaction`, passingValues)
          .then((res) => {
            const data = res.data;
            if (data.success == true) {
              this.showToast(
                "Sucesso!",
                "success",
                "Pagamento efectuado com sucesso"
              );
              const logsParams = logs(
                this.user,
                `${passingValues.description}`,
                "Desembolso de crédito"
              );
              this.$store.dispatch("addLog", logsParams);
              if (parseFloat(this.debitBalance) > 0) this.insertDebt();
            } else {
              this.showToast("Erro!", "danger", data.message);
            }
            this.getAmortizationLoans();
            this.getLoanDebts();
            this.getCustomerTranzactions();
            this.$refs["place-debt-payment"].hide();
            this.$store.commit("LOADING_STATUS", false);
          })
          .catch((err) => {
            this.showToast("Erro!", "danger", err.message);
            this.$store.commit("LOADING_STATUS", false);
            this.$refs["place-debt-payment"].hide();
          });
      }
    },

    getCustomerTranzactions() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .get(`/api/tranzaction/${this.currentCustomer.accountNumber}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.$store.commit("SET_CUSTOMER_TRANZACTIONS", data.result);
          } else {
            this.showToast("Erro!", "danger", data.message);
            this.$store.commit("SET_CUSTOMER_TRANZACTIONS", []);
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.$store.commit("SET_CUSTOMER_TRANZACTIONS", []);
        });
    },

    insertDebt() {
      this.$store.commit("LOADING_STATUS", true);
      const passingValues = {
        companyId: this.company.id,
        accountNumber: this.currentCustomer.accountNumber,
        loanId: this.currentLoan.id,
        amortisationId: this.currentAmortization.id,
        debtAmount: this.debitBalance,
        updatedBy: this.user.name,
        dateInserted: this.paymentDate,
      };

      axios
        .post(`/api/debt`, passingValues)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);
          } else {
            this.showToast("Aviso!", "danger", data.message);
          }
        })
        .catch((err) => {
          console.log(err);
          this.showToast("Aviso!", "danger", err.message);
        });
      this.$store.commit("LOADING_STATUS", true);
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },

    onFileChange(e) {
      this.selectedFile = e.target.files[0];
      console.log(this.selectedFile);
      this.onUploadFile();
    },

    onUploadFile() {
      if (!this.selectedFile) {
        this.showToast(
          "Erro!",
          "warning",
          "Seleccione um documento por favor!"
        );
        return;
      }
      let formData = new FormData();
      formData.append("file", this.selectedFile);
      this.$store.commit("LOADING_STATUS", true);
      axios
        .post(`/api/upload`, formData)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.uploadValue = 100;
            this.receiptUrl = data.documentFileUrl || `/documents/${data.imageUrl}`;
          } else {
            this.showToast("Erro!", "danger", data.message);
          }
          this.$store.commit("LOADING_STATUS", false);
          this.uploadValue = 0;
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.uploadValue = 0;
        });
    },
  },
};
</script>

