import DateFormat from "./dateFormat";
import MoneyFormat from "./moneyFormat";
import moment from "moment";

const today = moment();

const getCapital = (payment) => {
  return (
    payment.amount - payment.interestRateAmount - payment.latePaymentInterest
  );
};

const getPaymentMethod = (method) => {
  if (method == 1) {
    return "Boca do Caixa";
  } else if (method == 2) {
    return "Depósito Bancário";
  } else if (method == 3) {
    return "Transferência Bancária";
  } else if (method == 4) {
    return "POS";
  } else if (method == 5) {
    return "Cheque";
  } else if (method == 6) {
    return "SISTAFE";
  } else if (method == 7) {
    return "M-Pesa Open-Api";
  } else if (method == 8) {
    return "E-Mola";
  }
};

const calculateMissedDays = (row) => {
  return today.diff(row.dueDate, "days");
};

class AmmortizationPlan {
  static getAmmortization(ammortizations) {
    const body = [];

    for (let row of ammortizations) {
      const rows = [];

      rows.push({ text: row.installmentOrder, fontSize: 8 });
      rows.push({ text: DateFormat.formatDate(row.dueDate), fontSize: 8 });
      rows.push({
        text: MoneyFormat.formatMoney(row.amortization),
        fontSize: 8,
        alignment: "right",
      });
      rows.push({
        text: MoneyFormat.formatMoney(row.rateAmount),
        fontSize: 8,
        alignment: "right",
      });
      rows.push({
        text: MoneyFormat.formatMoney(row.installment),
        fontSize: 8,
        alignment: "right",
      });
      body.push(rows);
    }
    return body;
  }

  static getLoanGuarantees(guarantees) {
    const items = [];
    for (let item of guarantees) {
      items.push({
        text: `${item.guaranteeDescription}`,
        fontSize: 8,
        bold: false,
      });
    }
    return items;
  }

  static getAmmortizationLoans(ammortizations) {
    const body = [];

    for (let row of ammortizations) {
      const rows = [];

      rows.push({ text: row.installmentOrder, fontSize: 8 });
      rows.push({ text: DateFormat.formatDate(row.dueDate), fontSize: 8 });
      rows.push({
        text: MoneyFormat.formatMoney(row.amortization),
        fontSize: 8,
        alignment: "right",
      });
      rows.push({
        text: MoneyFormat.formatMoney(row.rateAmount),
        fontSize: 8,
        alignment: "right",
      });
      rows.push({
        text: calculateMissedDays(row),
        fontSize: 8,
        alignment: "right",
      });
      rows.push({
        text: MoneyFormat.formatMoney(row.installment),
        fontSize: 8,
        alignment: "right",
      });
      rows.push({ text: row.status == 0 ? "Não pago" : "Pago", fontSize: 8 });
      body.push(rows);
    }
    return body;
  }

  static getLoanGuaranteesList(loanGuarantees) {
    const body = [];
    let count = 1;

    for (let row of loanGuarantees) {
      const rows = [];

      rows.push({ text: count, fontSize: 8 });
      rows.push({ text: row.guaranteeDescription, fontSize: 8 });
      rows.push({ text: DateFormat.formatDate(row.createdAt), fontSize: 8 });
      rows.push({
        text: MoneyFormat.formatMoney(row.purchaseAmount),
        fontSize: 8,
        alignment: "right",
      });
      body.push(rows);
    }
    count++;
    return body;
  }

  static getPaymentBody(tranzactions) {
    const body = [];

    for (let row of tranzactions) {
      const rows = [];

      rows.push({ text: DateFormat.formatDate(row.createdAt), fontSize: 8 });
      rows.push({
        text: getPaymentMethod(row.paymentMethod),
        fontSize: 7,
        alignment: "left",
      });
      rows.push({
        text: row.tranzactionReference,
        fontSize: 7,
        alignment: "left",
      });
      rows.push({
        text: MoneyFormat.formatMoney(getCapital(row)),
        fontSize: 7,
        alignment: "left",
      });
      rows.push({
        text: MoneyFormat.formatMoney(row.interestRateAmount),
        fontSize: 7,
        alignment: "right",
      });
      rows.push({
        text: MoneyFormat.formatMoney(row.latePaymentInterest),
        fontSize: 7,
        alignment: "right",
      });
      rows.push({
        text: MoneyFormat.formatMoney(row.amount),
        fontSize: 7,
        alignment: "right",
      });
      body.push(rows);
    }
    return body;
  }
}

export default AmmortizationPlan;
